#include "settlement/SettlementRuntime.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::settlement{
bool SettlementRuntime::publish(SettlementTierDefinition d){if(!d.contentId||d.populationMetadataMin>d.populationMetadataMax)return false;tiers_[d.contentId]=d;return true;}bool SettlementRuntime::publish(SettlementFactionDefinition d){if(!d.contentId)return false;factions_[d.contentId]=d;return true;}bool SettlementRuntime::create(SettlementState s){if(!s.stableId||!s.siteStableId||!tiers_.contains(s.tierContentId)||!factions_.contains(s.factionContentId)||settlements_.contains(s.stableId))return false;const auto&t=tiers_.at(s.tierContentId);s.populationEstimate=std::clamp(s.populationEstimate,t.populationMetadataMin,t.populationMetadataMax);settlements_[s.stableId]=s;return true;}bool SettlementRuntime::setPower(std::uint64_t id,bool v){auto i=settlements_.find(id);if(i==settlements_.end())return false;i->second.powered=v;i->second.revision=elysium::safe::saturatingIncrement(i->second.revision);return true;}bool SettlementRuntime::setLod(std::uint64_t id,SettlementLodState v){auto i=settlements_.find(id);if(i==settlements_.end())return false;i->second.lod=v;i->second.revision=elysium::safe::saturatingIncrement(i->second.revision);return true;}const SettlementState*SettlementRuntime::find(std::uint64_t id)const{auto i=settlements_.find(id);return i==settlements_.end()?nullptr:&i->second;}std::uint32_t SettlementRuntime::services(std::uint64_t id)const{auto s=find(id);if(!s)return 0;auto ti=tiers_.find(s->tierContentId);auto fi=factions_.find(s->factionContentId);if(ti==tiers_.end()||fi==factions_.end())return 0;return (ti->second.baseServices|fi->second.addServices)&~fi->second.removeServices;}SettlementServiceProjection SettlementRuntime::query(std::uint64_t id,SettlementService svc)const{SettlementServiceProjection o;o.settlementStableId=id;auto s=find(id);if(!s){o.block=SettlementServiceBlock::MissingSettlement;return o;}auto ti=tiers_.find(s->tierContentId);if(ti==tiers_.end()){o.block=SettlementServiceBlock::UnknownTier;return o;}auto fi=factions_.find(s->factionContentId);if(fi==factions_.end()){o.block=SettlementServiceBlock::UnknownFaction;return o;}const auto bit=settlementService(svc);if(!(services(id)&bit)){o.block=SettlementServiceBlock::CapabilityAbsent;return o;}if((fi->second.powerRequiredServices&bit)&&!s->powered){o.block=SettlementServiceBlock::MissingPower;return o;}o.available=true;o.requiresWake=s->lod==SettlementLodState::SleepingStrategic;o.block=SettlementServiceBlock::None;return o;}SettlementSnapshot SettlementRuntime::snapshot()const{SettlementSnapshot s;for(auto&[_,x]:tiers_)s.tiers.push_back(x);for(auto&[_,x]:factions_)s.factions.push_back(x);for(auto&[_,x]:settlements_)s.settlements.push_back(x);return s;}bool SettlementRuntime::restore(const SettlementSnapshot&s){SettlementRuntime r;for(auto x:s.tiers)if(!r.publish(x))return false;for(auto x:s.factions)if(!r.publish(x))return false;for(auto x:s.settlements)if(!r.create(x))return false;*this=std::move(r);return true;}
} // namespace elysium::settlement
